"""Teacher scoring for on-policy distillation, including teachers with another tokenizer.

Every run names its teacher in a YAML (``teacher_tokenizer_path`` and
``opd_teacher_chat_template_kwargs``). When that vocabulary matches the student's,
the episode is scored on ``sample.tokens`` by Miles' existing path. Otherwise each
assistant turn is rendered with the teacher's own chat template — the conversation
as that teacher would have seen it on that turn — and the teacher's log-probs are
copied onto student tokens whose text the teacher covers exactly.

A position the teacher cannot judge keeps the student's rollout log-prob. The
sampled-token reverse KL is then zero there, so the position gets no distillation
signal. Observation tokens (loss mask 0) are left on the rollout log-probs.
"""

import asyncio
import copy
import difflib
import json
import logging
import math
from dataclasses import dataclass

import aiohttp
import torch

from miles.rollout import on_policy_distillation as opd
from miles.utils.types import Sample

logger = logging.getLogger(__name__)


def same_tokenizer(args) -> bool:
    """True when the teacher scores the episode on the student's token ids.

    Unset ``teacher_tokenizer_path`` is the historical single-tokenizer path.
    A set path still takes that path when the vocabularies are equal, so a
    Qwen3.5 teacher named in YAML scores exactly as it did before the YAML.
    """
    teacher_path = getattr(args, "teacher_tokenizer_path", None) or None
    student_path = getattr(args, "hf_checkpoint", None)
    key = (teacher_path, student_path)
    if getattr(args, "_opd_tokenizer_match_key", None) == key and hasattr(args, "_opd_tokenizer_match"):
        return args._opd_tokenizer_match
    if not teacher_path:
        args._opd_tokenizer_match_key = key
        args._opd_tokenizer_match = True
        return True
    student_tok, teacher_tok = _load_tokenizers(args)
    match = student_tok.get_vocab() == teacher_tok.get_vocab()
    args._opd_tokenizer_match_key = key
    args._opd_tokenizer_match = match
    return match


def _load_tokenizers(args):
    teacher_path = getattr(args, "teacher_tokenizer_path", None)
    student_path = getattr(args, "hf_checkpoint", None)
    if not teacher_path:
        raise ValueError("teacher_tokenizer_path is required to score a teacher with its own tokenizer.")
    if not student_path:
        raise ValueError("hf_checkpoint is required to compare the student and teacher tokenizers.")
    cached_key = (teacher_path, student_path)
    if getattr(args, "_opd_tokenizer_key", None) == cached_key and getattr(args, "_opd_student_tok", None) is not None:
        return args._opd_student_tok, args._opd_teacher_tok

    from transformers import AutoTokenizer

    args._opd_student_tok = AutoTokenizer.from_pretrained(student_path, trust_remote_code=True)
    args._opd_teacher_tok = AutoTokenizer.from_pretrained(teacher_path, trust_remote_code=True)
    args._opd_tokenizer_key = cached_key
    args._opd_decode_cache = {}
    return args._opd_student_tok, args._opd_teacher_tok


def _decode_token(tokenizer, token_id: int, cache: dict) -> str:
    key = (id(tokenizer), int(token_id))
    text = cache.get(key)
    if text is None:
        text = tokenizer.decode([int(token_id)], skip_special_tokens=False, clean_up_tokenization_spaces=False) or ""
        cache[key] = text
    return text


def _get_teacher_semaphore(args):
    loop = asyncio.get_running_loop()
    loop_key = id(loop)
    semaphores_by_loop = getattr(args, "_opd_teacher_semaphores", None)
    if semaphores_by_loop is None:
        semaphores_by_loop = {}
        args._opd_teacher_semaphores = semaphores_by_loop

    concurrency = int(getattr(args, "opd_teacher_concurrency", 0) or 0)
    if concurrency <= 0:
        return None

    semaphore = semaphores_by_loop.get(loop_key)
    if semaphore is None:
        semaphore = asyncio.Semaphore(concurrency)
        semaphores_by_loop[loop_key] = semaphore
    return semaphore


async def _post_teacher_once(session, teacher_url, payload):
    async with session.post(teacher_url, json=payload) as resp:
        if resp.status >= 400:
            body = (await resp.text())[:500]
            raise aiohttp.ClientResponseError(
                request_info=resp.request_info,
                history=resp.history,
                status=resp.status,
                message=f"{resp.reason}; body={body}",
                headers=resp.headers,
            )
        return await resp.json()


async def _post_teacher_json(args, teacher_url, payload, sample, warning_prefix):
    retries = max(0, int(getattr(args, "opd_teacher_retries", 2)))
    timeout = aiohttp.ClientTimeout(total=float(getattr(args, "opd_teacher_timeout", 300.0)))
    semaphore = _get_teacher_semaphore(args)
    last_exc = None

    for attempt in range(retries + 1):
        try:
            async with aiohttp.ClientSession(timeout=timeout) as session:
                if semaphore is None:
                    return await _post_teacher_once(session, teacher_url, payload)
                async with semaphore:
                    return await _post_teacher_once(session, teacher_url, payload)
        except (TimeoutError, asyncio.TimeoutError, aiohttp.ClientError, json.JSONDecodeError) as exc:
            last_exc = exc
            if attempt < retries:
                await asyncio.sleep(min(0.2 * (2**attempt), 2.0))
                continue

    logger.warning(
        "%s failed after %s attempt(s); those positions get no teacher signal "
        "(sample index=%s, input_tokens=%s): %s: %s",
        warning_prefix,
        retries + 1,
        getattr(sample, "index", None),
        len(payload.get("input_ids") or []),
        type(last_exc).__name__,
        last_exc,
    )
    return {"_opd_teacher_fallback": True, "_opd_teacher_fallback_reason": type(last_exc).__name__}


def _messages(args, sample: Sample):
    metadata = sample.metadata if isinstance(sample.metadata, dict) else {}
    key = getattr(args, "opd_prompt_messages_key", None) or "messages"
    messages = metadata.get(key)
    if isinstance(messages, list):
        return messages
    return None


def _tools(sample: Sample):
    metadata = sample.metadata if isinstance(sample.metadata, dict) else {}
    tools = metadata.get("tools")
    return tools if tools else None


def _template_kwargs(args) -> dict:
    raw = getattr(args, "opd_teacher_chat_template_kwargs", None) or {}
    return dict(raw) if isinstance(raw, dict) else {}


def _sanitize_messages(messages: list) -> list:
    """Stringify tool-call arguments and coerce null content, for templates that reject the stored form."""
    out = []
    for message in messages:
        if not isinstance(message, dict):
            out.append(message)
            continue
        message = dict(message)
        if message.get("content") is None and "content" in message:
            message["content"] = ""
        tool_calls = message.get("tool_calls")
        if tool_calls:
            rewritten = []
            for call in tool_calls:
                if not isinstance(call, dict):
                    rewritten.append(call)
                    continue
                call = dict(call)
                function = call.get("function")
                if isinstance(function, dict):
                    function = dict(function)
                    arguments = function.get("arguments")
                    if not isinstance(arguments, str):
                        function["arguments"] = json.dumps(arguments, ensure_ascii=False)
                    call["function"] = function
                rewritten.append(call)
            message["tool_calls"] = rewritten
        out.append(message)
    return out


def _render(tokenizer, messages, tools, template_kwargs, add_generation_prompt: bool) -> str:
    """Render ``messages`` with the teacher's chat template.

    YAML kwargs are applied first; ``tokenize`` and ``add_generation_prompt`` are then
    forced so a teacher config cannot turn this into an id-level render. Tool arguments
    stay as stored (dicts) on the first attempt — stringifying them changes spacing.
    """
    messages = copy.deepcopy(messages)
    tools = copy.deepcopy(tools) if tools else None

    def call(msgs, use_tools) -> str:
        kwargs = dict(template_kwargs or {})
        kwargs["tokenize"] = False
        kwargs["add_generation_prompt"] = add_generation_prompt
        if use_tools and tools:
            kwargs["tools"] = tools
        text = tokenizer.apply_chat_template(msgs, **kwargs)
        if not isinstance(text, str):
            raise TypeError(f"chat template returned {type(text).__name__}, expected str")
        return text

    try:
        return call(messages, True)
    except TypeError:
        return call(messages, False)
    except Exception:
        sanitized = _sanitize_messages(messages)
        try:
            return call(sanitized, True)
        except TypeError:
            return call(sanitized, False)


def _tokenize_with_offsets(tokenizer, text: str) -> tuple[list[int], list[tuple[int, int]]]:
    """Token ids and character offsets for ``text``.

    ``add_special_tokens=False`` matches ``apply_chat_template(..., tokenize=True)``:
    the template already emitted the special tokens it wants. Sending these ids to the
    teacher avoids a second, possibly different, tokenization on the server.
    """
    if getattr(tokenizer, "is_fast", False):
        encoded = tokenizer(text, add_special_tokens=False, return_offsets_mapping=True)
        ids = [int(i) for i in encoded["input_ids"]]
        offsets = [(int(a), int(b)) for a, b in encoded["offset_mapping"]]
        if len(offsets) != len(ids):
            raise ValueError("tokenizer offset mapping does not match input ids")
        return ids, offsets

    ids = [int(i) for i in tokenizer.encode(text, add_special_tokens=False)]
    offsets = []
    cursor = 0
    for token_id in ids:
        piece = tokenizer.decode([token_id], skip_special_tokens=False, clean_up_tokenization_spaces=False) or ""
        start = text.find(piece, cursor) if piece else cursor
        if piece and start >= 0:
            end = start + len(piece)
            offsets.append((start, end))
            cursor = end
        else:
            # No reliable span: the caller drops tokens with an empty span.
            offsets.append((cursor, cursor))
    return ids, offsets


def _delta_start(generation_prompt: str, completed: str) -> int:
    """Character where the completed render diverges from the generation prompt.

    Chat templates are not append-only: a thinking flag can put an empty ``<think>``
    block in the generation prompt and the real reasoning in the completed message.
    The common prefix is the context the teacher had already committed to; the
    remainder is the assistant turn as the teacher rendered it.
    """
    limit = min(len(generation_prompt), len(completed))
    index = 0
    while index < limit and generation_prompt[index] == completed[index]:
        index += 1
    return index


def _generation_spans(loss_mask) -> list[tuple[int, int]]:
    if loss_mask is None:
        return []
    if isinstance(loss_mask, torch.Tensor):
        mask = [int(x) for x in loss_mask.tolist()]
    else:
        mask = [int(x) for x in loss_mask]
    spans = []
    index = 0
    while index < len(mask):
        if mask[index]:
            end = index + 1
            while end < len(mask) and mask[end]:
                end += 1
            spans.append((index, end))
            index = end
        else:
            index += 1
    return spans


def _rollout_log_probs(sample: Sample) -> list[float]:
    """Rollout log-probs aligned to the response. Missing values are 0, matching observation spans."""
    resp_len = sample.response_length
    rollout = sample.rollout_log_probs
    if rollout is None:
        return [0.0] * resp_len
    if isinstance(rollout, torch.Tensor):
        values = rollout.detach().float().flatten().tolist()
    else:
        values = []
        for value in rollout:
            if value is None:
                values.append(0.0)
            else:
                values.append(float(value))
    if len(values) >= resp_len:
        return [float(v) for v in values[-resp_len:]]
    return [0.0] * (resp_len - len(values)) + [float(v) for v in values]


def _align_logprobs(
    student_texts: list[str],
    teacher_texts: list[str],
    teacher_lps: list[float | None],
) -> list[float | None]:
    """Map teacher log-probs onto student tokens whose text the teacher covers exactly.

    Character-level matching finds the shared writing. A student token receives the
    sum of the teacher log-probs of the one or more teacher tokens that tile it —
    that sum is the teacher's log-prob of that exact text. A teacher token that
    covers several student tokens is not split: those positions are not individually
    judgeable and stay unset.
    """
    assigned: list[float | None] = [None] * len(student_texts)
    if not student_texts or not teacher_texts:
        return assigned

    student_spans = []
    cursor = 0
    for text in student_texts:
        student_spans.append((cursor, cursor + len(text)))
        cursor += len(text)
    student_string = "".join(student_texts)

    teacher_spans = []
    cursor = 0
    for text in teacher_texts:
        teacher_spans.append((cursor, cursor + len(text)))
        cursor += len(text)
    teacher_string = "".join(teacher_texts)
    if not student_string or not teacher_string:
        return assigned

    matcher = difflib.SequenceMatcher(None, student_string, teacher_string, autojunk=False)
    for block_s, block_t, size in matcher.get_matching_blocks():
        if size <= 0:
            continue
        student_end = block_s + size
        teacher_end = block_t + size
        inside = [
            (start, end, index)
            for index, (start, end) in enumerate(teacher_spans)
            if start >= block_t and end <= teacher_end and start < end
        ]
        if not inside:
            continue
        pointer = 0
        for student_index, (start, end) in enumerate(student_spans):
            if assigned[student_index] is not None or not (start >= block_s and end <= student_end and start < end):
                continue
            target_start = block_t + (start - block_s)
            target_end = block_t + (end - block_s)
            while pointer < len(inside) and inside[pointer][1] <= target_start:
                pointer += 1
            if pointer >= len(inside) or inside[pointer][0] != target_start:
                continue
            cursor_index = pointer
            covered = inside[cursor_index][1]
            chosen = [inside[cursor_index][2]]
            tiled = True
            while covered < target_end:
                cursor_index += 1
                if cursor_index >= len(inside) or inside[cursor_index][0] != covered:
                    tiled = False
                    break
                covered = inside[cursor_index][1]
                chosen.append(inside[cursor_index][2])
            if not tiled or covered != target_end:
                continue
            total = 0.0
            finite = True
            for teacher_index in chosen:
                value = teacher_lps[teacher_index]
                if value is None or not math.isfinite(value):
                    finite = False
                    break
                total += float(value)
            if finite:
                assigned[student_index] = total
    return assigned


@dataclass
class _Turn:
    span: tuple[int, int]
    full_ids: list[int]
    offsets: list[tuple[int, int]]
    delta_start: int
    full_len: int


def _plan_turns(args, sample: Sample, teacher_tok) -> tuple[list[_Turn] | None, str | None]:
    """Build one teacher rendering per assistant generation. None means the sample cannot be scored."""
    messages = _messages(args, sample)
    if not messages:
        return None, "no_messages"
    spans = _generation_spans(sample.loss_mask)
    if not spans:
        return [], None
    if any(end > sample.response_length for _, end in spans):
        return None, "loss_mask_longer_than_response"
    assistants = [index for index, message in enumerate(messages) if isinstance(message, dict) and message.get("role") == "assistant"]
    if len(assistants) < len(spans):
        return None, "fewer_assistants_than_generations"
    # Few-shot assistant turns live in the prompt. The generations are the trailing assistants.
    assistants = assistants[-len(spans) :]
    tools = _tools(sample)
    template_kwargs = _template_kwargs(args)
    turns = []
    for span, assistant_index in zip(spans, assistants, strict=True):
        try:
            generation_prompt = _render(teacher_tok, messages[:assistant_index], tools, template_kwargs, True)
            completed = _render(teacher_tok, messages[: assistant_index + 1], tools, template_kwargs, False)
            ids, offsets = _tokenize_with_offsets(teacher_tok, completed)
        except Exception as exc:
            logger.warning(
                "Teacher render failed; that turn gets no signal (sample index=%s, assistant=%s): %s: %s",
                getattr(sample, "index", None),
                assistant_index,
                type(exc).__name__,
                exc,
            )
            turns.append(_Turn(span=span, full_ids=[], offsets=[], delta_start=0, full_len=0))
            continue
        if len(offsets) != len(ids):
            turns.append(_Turn(span=span, full_ids=[], offsets=[], delta_start=0, full_len=0))
            continue
        turns.append(
            _Turn(
                span=span,
                full_ids=ids,
                offsets=offsets,
                delta_start=_delta_start(generation_prompt, completed),
                full_len=len(completed),
            )
        )
    return turns, None


def _prefix_chains(turns: list[_Turn]) -> list[list[int]]:
    """Group turn indexes whose token ids are prefixes of the next turn.

    The log-prob of token i depends only on tokens[:i], so a longer scored sequence
    supplies every shorter prefix. Text being a prefix is not enough: BPE can retokenize
    a shared prefix, and only equal ids are safe to slice.
    """
    chains: list[list[int]] = []
    current: list[int] = []
    for index, turn in enumerate(turns):
        if not turn.full_ids:
            if current:
                chains.append(current)
                current = []
            chains.append([index])
            continue
        if current and turns[current[-1]].full_ids == turn.full_ids[: len(turns[current[-1]].full_ids)]:
            current.append(index)
        else:
            if current:
                chains.append(current)
            current = [index]
    if current:
        chains.append(current)
    return chains


def _extract_logprobs(result, ids: list[int]) -> list[float | None] | None:
    if not isinstance(result, dict) or result.get("_opd_teacher_fallback"):
        return None
    meta = result.get("meta_info")
    if not isinstance(meta, dict):
        return None
    entries = meta.get("input_token_logprobs")
    if not isinstance(entries, list) or len(entries) != len(ids):
        return None
    log_probs: list[float | None] = []
    for index, entry in enumerate(entries):
        if not isinstance(entry, (list, tuple)) or len(entry) < 2 or entry[1] is None:
            return None
        if int(entry[1]) != int(ids[index]):
            return None
        value = entry[0]
        if value is None:
            log_probs.append(None)
            continue
        try:
            number = float(value)
        except (TypeError, ValueError):
            return None
        log_probs.append(number)
    return log_probs


async def _score_ids(args, sample: Sample, ids: list[int]) -> list[float | None] | None:
    if not ids:
        return None
    url = opd._teacher_url_for_sample(args, sample)
    payload = opd._score_payload(ids)
    result = await _post_teacher_json(args, url, payload, sample, "OPD teacher request")
    extracted = _extract_logprobs(result, ids)
    if extracted is None and not (isinstance(result, dict) and result.get("_opd_teacher_fallback")):
        logger.warning(
            "OPD teacher reply did not match the sent token ids; that span gets no teacher signal "
            "(sample index=%s, input_tokens=%s)",
            getattr(sample, "index", None),
            len(ids),
        )
    return extracted


def _teacher_delta(turn: _Turn, tokenizer, log_probs: list[float | None] | None, cache: dict):
    if not log_probs or len(log_probs) != len(turn.full_ids):
        return [], []
    texts = []
    values = []
    for index, ((start, end), token_id) in enumerate(zip(turn.offsets, turn.full_ids, strict=True)):
        # Drop tokens that straddle the generation boundary or carry no character span.
        if start >= turn.delta_start and end <= turn.full_len and start < end:
            texts.append(_decode_token(tokenizer, token_id, cache))
            values.append(log_probs[index])
    return texts, values


async def score_episode(args, sample: Sample, **kwargs) -> dict:
    """Score one episode and return response-aligned teacher log-probs.

    Unjudgeable positions already hold the rollout log-prob. ``fallback`` is set only
    when the episode could not be scored at all.
    """
    student_tok, teacher_tok = _load_tokenizers(args)
    rollout = _rollout_log_probs(sample)
    trained = [index for index, bit in enumerate(_mask_bits(sample.loss_mask, sample.response_length)) if bit]
    base = {
        "teacher_log_probs": rollout,
        "n_signaled": 0,
        "n_trained": len(trained),
        "fallback": False,
        "fallback_reason": None,
    }
    if len(sample.tokens) < sample.response_length:
        base["fallback"] = True
        base["fallback_reason"] = "short_tokens"
        logger.warning("Sample index=%s has fewer tokens than response_length; no teacher signal", sample.index)
        return base

    turns, reason = _plan_turns(args, sample, teacher_tok)
    if turns is None:
        base["fallback"] = True
        base["fallback_reason"] = reason or "unscorable"
        logger.warning(
            "Sample index=%s cannot be scored with the teacher template (%s); no teacher signal",
            sample.index,
            base["fallback_reason"],
        )
        return base
    if not turns:
        return base

    cache = getattr(args, "_opd_decode_cache", None)
    if cache is None:
        cache = {}
        args._opd_decode_cache = cache

    chains = _prefix_chains(turns)
    scored: list[list[float | None] | None] = [None] * len(turns)

    async def score_chain(chain: list[int]) -> None:
        longest = turns[chain[-1]]
        if not longest.full_ids:
            return
        log_probs = await _score_ids(args, sample, longest.full_ids)
        if log_probs is None:
            return
        for index in chain:
            length = len(turns[index].full_ids)
            scored[index] = log_probs[:length]

    await asyncio.gather(*(score_chain(chain) for chain in chains))

    prompt_len = len(sample.tokens) - sample.response_length
    response_ids = sample.tokens[prompt_len:]
    assigned = list(rollout)
    n_signaled = 0
    for turn, log_probs in zip(turns, scored, strict=True):
        start, end = turn.span
        student_ids = response_ids[start:end]
        student_texts = [_decode_token(student_tok, token_id, cache) for token_id in student_ids]
        teacher_texts, teacher_lps = _teacher_delta(turn, teacher_tok, log_probs, cache)
        turn_assigned = _align_logprobs(student_texts, teacher_texts, teacher_lps)
        for offset, value in enumerate(turn_assigned):
            if value is None:
                continue
            assigned[start + offset] = value
            n_signaled += 1
    base["teacher_log_probs"] = assigned
    base["n_signaled"] = n_signaled
    return base


def _mask_bits(loss_mask, response_length: int) -> list[int]:
    if loss_mask is None:
        return [0] * response_length
    if isinstance(loss_mask, torch.Tensor):
        bits = [int(x) for x in loss_mask.tolist()]
    else:
        bits = [int(x) for x in loss_mask]
    if len(bits) >= response_length:
        return bits[:response_length]
    return bits + [0] * (response_length - len(bits))


def apply_teacher_log_probs(sample: Sample, result: dict) -> None:
    """Write ``sample.teacher_log_probs`` and the cross-vocab overlap metadata."""
    values = result["teacher_log_probs"]
    if len(values) != sample.response_length:
        raise ValueError(
            f"teacher_log_probs length ({len(values)}) != response_length ({sample.response_length}) "
            f"for sample index={sample.index}"
        )
    sample.teacher_log_probs = torch.tensor(values, dtype=torch.float32)
    if sample.metadata is None:
        sample.metadata = {}
    trained = int(result.get("n_trained") or 0)
    signaled = int(result.get("n_signaled") or 0)
    sample.metadata["cross_vocab_token_overlap"] = (signaled / trained) if trained else 0.0
    if result.get("fallback"):
        sample.metadata["opd_teacher_fallback"] = True
        sample.metadata["opd_teacher_fallback_reason"] = result.get("fallback_reason") or "teacher_failed"

